select 'sat_order' as relation_name where (select count(*) from (select order_hk, order_hashdiff, load_dts, lag(order_hashdiff) over (partition by order_hk order by load_dts) previous from (select distinct order_hk, order_hashdiff, load_dts from {{ ref('stg_orders') }}) d) v where order_hashdiff is distinct from previous) <> (select count(*) from {{ ref('sat_order') }})
union all
select 'sat_order_status' as relation_name where (select count(*) from (select order_hk, order_status_hashdiff, load_dts, lag(order_status_hashdiff) over (partition by order_hk order by load_dts) previous from (select distinct order_hk, order_status_hashdiff, load_dts from {{ ref('stg_orders') }}) d) v where order_status_hashdiff is distinct from previous) <> (select count(*) from {{ ref('sat_order_status') }})
union all
select 'sat_order_item' as relation_name where (select count(*) from (select order_item_hk, order_item_hashdiff, load_dts, lag(order_item_hashdiff) over (partition by order_item_hk order by load_dts) previous from (select distinct order_item_hk, order_item_hashdiff, load_dts from {{ ref('stg_order_items') }}) d) v where order_item_hashdiff is distinct from previous) <> (select count(*) from {{ ref('sat_order_item') }})
union all
select 'sat_customer_profile' as relation_name where (select count(*) from (select customer_profile_hk, customer_profile_hashdiff, load_dts, lag(customer_profile_hashdiff) over (partition by customer_profile_hk order by load_dts) previous from (select distinct customer_profile_hk, customer_profile_hashdiff, load_dts from {{ ref('stg_customers') }}) d) v where customer_profile_hashdiff is distinct from previous) <> (select count(*) from {{ ref('sat_customer_profile') }})
union all
select 'sat_product' as relation_name where (select count(*) from (select product_hk, product_hashdiff, load_dts, lag(product_hashdiff) over (partition by product_hk order by load_dts) previous from (select distinct product_hk, product_hashdiff, load_dts from {{ ref('stg_products') }}) d) v where product_hashdiff is distinct from previous) <> (select count(*) from {{ ref('sat_product') }})
union all
select 'sat_seller' as relation_name where (select count(*) from (select seller_hk, seller_hashdiff, load_dts, lag(seller_hashdiff) over (partition by seller_hk order by load_dts) previous from (select distinct seller_hk, seller_hashdiff, load_dts from {{ ref('stg_sellers') }}) d) v where seller_hashdiff is distinct from previous) <> (select count(*) from {{ ref('sat_seller') }})
union all
select 'sat_category' as relation_name where (select count(*) from (select category_hk, category_hashdiff, load_dts, lag(category_hashdiff) over (partition by category_hk order by load_dts) previous from (select distinct category_hk, category_hashdiff, load_dts from {{ ref('stg_product_category_translation') }}) d) v where category_hashdiff is distinct from previous) <> (select count(*) from {{ ref('sat_category') }})
union all
select 'sat_review' as relation_name where (select count(*) from (select review_hk, review_hashdiff, load_dts, lag(review_hashdiff) over (partition by review_hk order by load_dts) previous from (select distinct review_hk, review_hashdiff, load_dts from {{ ref('stg_order_reviews') }}) d) v where review_hashdiff is distinct from previous) <> (select count(*) from {{ ref('sat_review') }})
